import { categories, issueRepository, DEMO_DATE } from './data.js';
import { CivicMap } from './map.js';

const paths={map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2V5zm6-2v16m6-14v16',database:'M21 5c0 2-4 3-9 3S3 7 3 5s4-3 9-3 9 1 9 3zm0 0v14c0 2-4 3-9 3s-9-1-9-3V5m0 7c0 2 4 3 9 3s9-1 9-3',chart:'M4 20V10h4v10m4 0V4h4v16m4 0V8h3v12M2 20h22',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',bookmark:'M6 3h12v18l-6-4-6 4V3z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0z',check:'M5 12l4 4L20 5',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4zm-5 10 3 3 7-7',settings:'M9 3h6l1 4 4 1 2 5-3 3 1 4-5 2-3-3-4 1-3-4 2-4-2-3 4-2V3zm6 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0z',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0z',search:'M10 18a8 8 0 1 1 0-16 8 8 0 0 1 0 16zm6-2 6 6',filter:'M3 6h18M7 3v6M3 12h18m-6-3v6M3 18h18m-12-3v6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0z',warning:'M12 3 2 21h20L12 3zm0 6v5m0 3h.01',cone:'M8 17l3-14h2l3 14M9 9h6M8 14h8M4 21v-4h16v4H4z',tool:'m4 3 17 17-3 2L2 6l2-3zm17 0-5 1-2 5-8 8-3 1-1 4 4-1 1-3 8-8 5-2 1-5z',trash:'M3 6h18M8 6V3h8v3M5 6l1 16h12l1-16M9 10v8m6-8v8',water:'M2 6c4-6 5 6 10 0s6 5 10 0M2 12c4-6 5 6 10 0s6 5 10 0M2 18c4-6 5 6 10 0s6 5 10 0',more:'M4 12h.01M12 12h.01M20 12h.01',close:'m6 6 12 12M6 18 18 6',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',layers:'m12 2 10 6-10 6L2 8l10-6zM2 12l10 6 10-6M2 16l10 6 10-6',box:'M3 8V3h5m8 0h5v5m0 8v5h-5m-8 0H3v-5',hand:'M8 12V5a2 2 0 0 1 4 0v7-9a2 2 0 0 1 4 0v9-6a2 2 0 0 1 4 0v10c0 4-3 6-7 6-3 0-4-1-6-4l-4-5a2 2 0 0 1 3-2l2 2z',plus:'M12 5v14M5 12h14',minus:'M5 12h14',target:'M12 2v4m0 12v4M2 12h4m12 0h4M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0z',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',image:'M3 3h18v18H3V3zm0 13 5-5 5 5 3-3 5 5M15 7h.01',code:'m8 5-7 7 7 7m8-14 7 7-7 7m-3-16-2 18',refresh:'M20 8a9 9 0 1 0 1 8m-1-14v6h-6',person:'M15 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0zM5 11l7-3 7 3m-7-3v8m0 0-4 7m4-7 4 7',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M6 6l1 1m10 10 1 1M6 18l1-1M17 7l1-1M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0z'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.pin}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(`civiclens:${key}`))??fallback;}catch{return fallback;}};
const persist=(key,value)=>{try{localStorage.setItem(`civiclens:${key}`,JSON.stringify(value));}catch{toast('Browser storage is unavailable. Changes will last for this session.');}};
const state={issues:[],view:'map',filters:{query:'',type:'',severity:'',days:'30',area:'',status:'',infra:'',radius:'500'},selected:[],scope:null,panel:null,saved:read('saved',[]),recent:read('recent',[]),pending:read('pending',[]),role:'Public',sort:'first_seen_at',direction:-1,page:1,perPage:10,layers:[],mapMode:'pan',heat:false,center:[-79.397,43.661],zoom:13,historyEnabled:read('historyEnabled',true)};
let map,uploadDraft={photos:[],category:'',description:'',address:'',confirmed:false},toastTimer;
const app=document.querySelector('#app');
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
const typeIcon=type=>icon(categories[type]?.icon||'pin');
const badge=(text,kind='')=>`<span class="badge ${kind||text.toLowerCase().replaceAll(' ','-')}">${esc(text)}</span>`;
const date=value=>new Date(value).toLocaleDateString('en-CA',{month:'short',day:'numeric',timeZone:'America/Toronto'});
const age=i=>Math.max(0,Math.floor((Date.parse(DEMO_DATE)-Date.parse(i.first_seen_at))/86400000));
function filtered(){const f=state.filters;return state.issues.filter(i=>(!f.query||[i.issue_id,i.address,i.neighbourhood_id,i.issue_type,i.asset_name,i.description].join(' ').toLowerCase().includes(f.query.toLowerCase()))&&(!f.type||i.issue_type===f.type)&&(!f.severity||i.severity===f.severity)&&(!f.area||i.neighbourhood_id===f.area)&&(!f.status||i.resolution_status===f.status)&&(!f.days||age(i)<Number(f.days))&&(!f.infra||(i.infrastructure_type===f.infra&&i.distance_m<=Number(f.radius))));}
function remember(issue){if(!state.historyEnabled)return;state.recent=[issue.issue_id,...state.recent.filter(id=>id!==issue.issue_id)].slice(0,20);persist('recent',state.recent);}
function toggleSave(ids){const all=ids.every(id=>state.saved.includes(id));state.saved=all?state.saved.filter(id=>!ids.includes(id)):[...new Set([...state.saved,...ids])];persist('saved',state.saved);toast(all?'Removed from saved issues':'Saved to this browser');render();}
function nav(view){if(map){state.center=map.center;state.zoom=map.zoom;}state.view=view;state.page=1;if(view==='data')state.scope=null;state.panel=null;state.selected=[];history.replaceState(null,'',`#${view}`);render();window.scrollTo(0,0);}
function openIssue(id,back=null){const i=state.issues.find(i=>i.issue_id===id);if(!i)return;remember(i);state.panel={mode:'issue',id,back};if(!state.selected.includes(id))state.selected=[id];renderPanel();map?.setData(filtered(),state.selected);}
function selectMap(ids,mode,e){
  if(e?.shiftKey){for(const id of ids)state.selected=state.selected.includes(id)?state.selected.filter(x=>x!==id):[...state.selected,id];state.panel=state.selected.length?{mode:'multi',ids:[...state.selected]}:null;}
  else {state.selected=ids;state.panel=ids.length?mode==='issue'?{mode,id:ids[0]}:{mode,ids}:null;if(mode==='issue')remember(state.issues.find(i=>i.issue_id===ids[0]));}
  renderPanel();map?.setData(filtered(),state.selected);
}
function clearSelection(){state.selected=[];state.panel=null;renderPanel();map?.setData(filtered(),[]);}
function scopedTable(ids){state.scope=[...ids];state.view='data';state.panel=null;state.page=1;history.replaceState(null,'','#data');render();}

function render(){
  if(map){state.center=map.center;state.zoom=map.zoom;map.destroy();map=null;}
  const headings={map:['Map Explorer','Explore the city. See what needs attention.'],data:['Data Explorer','One city. One dataset. Every issue in view.'],dashboard:['City overview','A clearer picture of Toronto’s public spaces.'],saved:['Saved workspace','Your bookmarked issues, ready when you are.'],recents:['Recently viewed','Pick up where you left off.'],verify:['Verification queue','A human perspective behind every confident pin.']};
  const [title,subtitle]=headings[state.view]||headings.map;
  app.innerHTML=`<aside class="sidebar"><a class="brand" href="#map" data-nav="map" aria-label="CivicLens home"><span class="brand-mark"><i></i></span><span>Civic<span class="cyan">Lens</span></span></a><div class="workspace-label">TORONTO WORKSPACE <span class="live-dot"></span></div><nav aria-label="Main navigation">${[['map','map','Map Explorer'],['data','database','Data Explorer'],['dashboard','chart','Dashboard']].map(([v,i,t])=>navItem(v,i,t)).join('')}<div class="nav-divider"></div><span class="nav-section">YOUR WORKSPACE</span>${[['saved','bookmark','Saved'],['recents','clock','Recents']].map(([v,i,t])=>navItem(v,i,t,v==='saved'?state.saved.length:null)).join('')}${state.role!=='Public'?navItem('verify','shield','Verify',state.pending.length+state.issues.filter(i=>i.verification_status==='Needs review').length):''}</nav><button class="button primary upload-button" data-action="upload" aria-label="Upload new issue">${icon('plus')}<span>Upload new issue</span></button><div class="sidebar-note">Small observations.<br><strong>Better neighbourhoods.</strong><span>A little attention goes a long way.</span></div><div class="sidebar-bottom"><button class="nav-item" data-action="settings" aria-label="Settings">${icon('settings')}<span>Settings</span></button><button class="nav-item" data-action="help" aria-label="Help and methodology">${icon('help')}<span>Help & methodology</span></button><div class="account"><span class="avatar">JD</span><div><strong>Jamie Davis</strong><select id="role-select" aria-label="Demo account type"><option ${state.role==='Public'?'selected':''}>Public</option><option ${state.role==='Volunteer'?'selected':''}>Volunteer</option><option ${state.role==='City Staff'?'selected':''}>City Staff</option></select></div><span class="account-dots">···</span></div></div></aside>
  <main class="main ${state.view==='map'?'map-page':''}"><header class="page-header"><div><div class="eyebrow">CIVIC INTELLIGENCE <span>/</span> TORONTO, ON</div><h1>${title}</h1><p>${subtitle}</p></div><div class="header-right"><span class="demo-label"><span></span> Demo workspace</span><button class="icon-button" data-action="help" aria-label="About this demo">${icon('help')}</button></div></header>
  <div class="filterbar">${filtersHtml()}</div>${secondaryFilters()}
  <div class="workspace-content" id="workspace-content">${state.view==='map'?mapHtml():state.view==='data'?dataHtml():state.view==='dashboard'?dashboardHtml():state.view==='verify'?verifyHtml():collectionHtml()}</div>
  ${state.view!=='map'?'<footer class="page-footer"><span>CivicLens · Built for a more responsive city</span><span>Fictional sample data · Snapshot: Oct 17, 2026</span></footer>':''}</main>`;
  bindShell();
  if(state.view==='map')initMap();
  if(state.view==='data')bindTable();
  bindIssueLinks(app);
}
function navItem(view,i,title,count){return `<button class="nav-item ${state.view===view?'active':''}" data-nav="${view}" aria-label="${title}" ${state.view===view?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`;}
function selectHtml(key,label,values,ic){return `<label class="filter-select">${icon(ic)}<select data-filter="${key}" aria-label="${label}"><option value="">${label}</option>${values.map(v=>{const [value,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(value)}" ${state.filters[key]===String(value)?'selected':''}>${esc(text)}</option>`;}).join('')}</select></label>`;}
function filtersHtml(){return `<label class="search-field">${icon('search')}<input id="global-search" placeholder="Search issues, places, or IDs…" value="${esc(state.filters.query)}" aria-label="Search issues, places, or IDs"><kbd>/</kbd></label>${selectHtml('type','All issue types',Object.keys(categories),'filter')}${selectHtml('severity','All severities',['High','Medium','Low'],'warning')}${selectHtml('days','Any time',[[7,'Last 7 days'],[30,'Last 30 days']],'clock')}${selectHtml('area','All areas (Toronto)',[...new Set(state.issues.map(i=>i.neighbourhood_id))].sort(),'pin')}<button class="reset-button" data-action="reset" title="Reset all filters">${icon('refresh')}<span>Reset</span></button>`;}
function secondaryFilters(){return `<div class="filter-context"><span class="sync-label"><span class="live-dot"></span> Shared filters across map & data</span><div class="context-actions">${state.filters.infra?`<span class="scope-chip">${esc(state.filters.infra)} · within ${state.filters.radius}m <button data-action="clear-infra" aria-label="Clear infrastructure filter">×</button></span>`:''}<button class="text-button" data-action="proximity">${icon('layers')} Infrastructure & proximity</button><span class="context-divider"></span><span><strong>${filtered().length}</strong> sample issues</span></div></div>`;}
function mapHtml(){return `<div class="map-workspace"><div id="city-map" class="city-map" role="region" aria-label="Interactive Toronto issue map"></div><div class="map-top-left"><div class="map-segment"><button class="${!state.heat?'active':''}" data-action="pins">${icon('pin')} Pins</button><button class="${state.heat?'active':''}" data-action="heat">${icon('water')} Density</button></div><span class="map-demo">FICTIONAL ISSUE LOCATIONS</span></div><div class="map-top-right"><button class="map-control ${state.mapMode==='pan'?'active':''}" data-action="pan" title="Pan map" aria-label="Pan map">${icon('hand')}</button><button class="map-control ${state.mapMode==='box'?'active':''}" data-action="box" title="Box select" aria-label="Box select">${icon('box')}</button><button class="map-control" data-action="layers" title="Infrastructure layers" aria-label="Infrastructure layers">${icon('layers')}</button></div><div class="map-bottom-left"><div class="map-summary"><span class="live-dot"></span> Toronto, Ontario <span class="muted">· ${filtered().length} sample issues</span><button data-action="search-area" class="text-button">Search this area</button></div><div class="map-legend">${Object.entries(categories).map(([type,c])=>`<button data-legend="${type}" class="${state.filters.type===type?'legend-active':''}"><span style="color:${c.color}">${typeIcon(type)}</span>${type}</button>`).join('')}</div></div><div class="map-bottom-right"><button class="map-control street-person" draggable="true" data-action="street" aria-label="Street-level explorer placeholder" title="Street-level imagery integration">${icon('person')}</button><div class="zoom-controls"><button class="map-control" data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><button class="map-control" data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button></div><button class="map-control" data-action="center" title="Reset Toronto view" aria-label="Reset Toronto view">${icon('target')}</button></div><div class="map-hint">${icon(state.mapMode==='box'?'box':'hand')} ${state.mapMode==='box'?'Drag a rectangle to select issues':'Drag to pan · Scroll to zoom · Shift + click to select'}</div><div class="map-attribution">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors</div><aside id="issue-panel" class="issue-panel" aria-label="Selected issues" hidden></aside></div>`;}
function initMap(){map=new CivicMap(document.querySelector('#city-map'),{onSelect:selectMap,onEmpty:clearSelection,onMove:()=>{},icon:typeIcon});map.center=state.center;map.zoom=state.zoom;map.mode=state.mapMode;map.layers=state.layers;map.showHeat=state.heat;map.setData(filtered(),state.selected);renderPanel();
  document.querySelectorAll('[data-legend]').forEach(b=>b.onclick=()=>{state.filters.type=state.filters.type===b.dataset.legend?'':b.dataset.legend;render();});
  const person=document.querySelector('.street-person');person.ondragstart=e=>{e.dataTransfer.setData('text/plain','civiclens-street');document.querySelector('#city-map').classList.add('coverage-preview');};person.ondragend=()=>document.querySelector('#city-map')?.classList.remove('coverage-preview');
  document.querySelector('#city-map').ondragover=e=>e.preventDefault();document.querySelector('#city-map').ondrop=e=>{e.preventDefault();document.querySelector('#city-map').classList.remove('coverage-preview');streetModal();};
}
function renderPanel(){const el=document.querySelector('#issue-panel');if(!el)return;el.hidden=!state.panel;document.querySelector('.map-workspace').classList.toggle('panel-open',!!state.panel);if(!state.panel)return;
  const p=state.panel;
  if(p.mode==='issue'){const i=state.issues.find(i=>i.issue_id===p.id);el.innerHTML=`<div class="panel-heading"><button class="text-button" data-action="panel-back">${icon('back')} ${p.back?'Back to results':'Issue details'}</button><button class="icon-button" data-action="close-panel" aria-label="Close issue details">${icon('close')}</button></div>${detailHtml(i)}<div class="panel-footer"><button class="button" data-action="save-issue">${icon('bookmark')} ${state.saved.includes(i.issue_id)?'Saved':'Save issue'}</button><button class="button" data-action="share-issue">${icon('external')} Share</button></div>`;
    el.querySelector('[data-action="save-issue"]').onclick=()=>toggleSave([i.issue_id]);el.querySelector('[data-action="share-issue"]').onclick=()=>shareIssue(i);el.querySelector('[data-action="panel-back"]').onclick=()=>{if(p.back){state.panel=p.back;renderPanel();}else clearSelection();};
  }else{const issues=p.ids.map(id=>state.issues.find(i=>i.issue_id===id)).filter(Boolean);el.innerHTML=`<div class="panel-heading"><div><span class="eyebrow">${p.mode==='cluster'?'MAP CLUSTER':'YOUR SELECTION'}</span><h2>${issues.length} issues selected</h2></div><button class="icon-button" data-action="close-panel" aria-label="Close selection">${icon('close')}</button></div><div class="panel-info">${p.mode==='cluster'?'Grouped at this zoom level. These may be separate incidents.':'Shift + click markers to add or remove issues.'}</div><div class="panel-list-controls"><input id="panel-search" placeholder="Filter selected issues…" aria-label="Filter selected issues"><select id="panel-sort" aria-label="Sort selected issues"><option value="date">Newest first</option><option value="severity">Severity</option><option value="type">Issue type</option></select></div><div class="selection-summary">${issues.filter(i=>i.severity==='High').length} high priority <span>·</span> ${issues.filter(i=>i.verification_status==='Verified').length} verified</div><div id="panel-results" class="panel-results"></div><div class="panel-footer wrap"><button class="button primary" data-action="selection-table">${icon('database')} View as table</button>${p.mode==='cluster'?'<button class="button" data-action="cluster-zoom">Zoom in ↗</button>':''}<button class="button" data-action="save-selection">${icon('bookmark')} Save selection</button></div>`;
    const updateList=()=>{const query=el.querySelector('#panel-search').value.toLowerCase(),sort=el.querySelector('#panel-sort').value;const rows=issues.filter(i=>`${i.address} ${i.issue_type}`.toLowerCase().includes(query)).sort((a,b)=>sort==='severity'?['High','Medium','Low'].indexOf(a.severity)-['High','Medium','Low'].indexOf(b.severity):sort==='type'?a.issue_type.localeCompare(b.issue_type):b.first_seen_at.localeCompare(a.first_seen_at));el.querySelector('#panel-results').innerHTML=rows.length?rows.map(i=>issueRow(i)).join(''):emptyHtml('No matching issues','Try a different search.');el.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>openIssue(b.dataset.issue,p));};updateList();el.querySelector('#panel-search').oninput=updateList;el.querySelector('#panel-sort').onchange=updateList;el.querySelector('[data-action="selection-table"]').onclick=()=>scopedTable(p.ids);el.querySelector('[data-action="save-selection"]').onclick=()=>toggleSave(p.ids);const zoom=el.querySelector('[data-action="cluster-zoom"]');if(zoom)zoom.onclick=()=>{const coords=issues.map(i=>i.geometry.coordinates);map.flyTo([coords.reduce((s,c)=>s+c[0],0)/coords.length,coords.reduce((s,c)=>s+c[1],0)/coords.length],Math.min(18,map.zoom+2));};
  }
  el.querySelector('[data-action="close-panel"]').onclick=clearSelection;
}
function detailHtml(i){return `<div class="detail-body"><div class="detail-title"><span class="type-orb" style="--type-color:${categories[i.issue_type]?.color||'#4ea8ff'}">${typeIcon(i.issue_type)}</span><div><span class="eyebrow">${esc(i.issue_id)} · SAMPLE RECORD</span><h2>${esc(i.issue_type)}</h2></div></div><div class="evidence-placeholder">${i.evidence_thumbnail?`<img src="${esc(i.evidence_thumbnail)}" alt="Issue evidence">`:`${icon('image')}<strong>Evidence photo</strong><span>Connect privacy-processed imagery here</span><small>PLACEHOLDER · NO REAL EVIDENCE</small>`}</div><div class="detail-badges">${badge(i.severity)} ${badge(i.resolution_status)} ${badge(i.verification_status)}</div><h3>${esc(i.address)}</h3><p>${esc(i.description)}</p><div class="confidence-note">${icon('target')}<div><strong>Approximate location · ${i.location_radius_m}m radius</strong><span>Location uncertainty is preserved in the public view.</span></div></div><div class="detail-grid"><div><span>Neighbourhood</span><strong>${esc(i.neighbourhood_id)}</strong></div><div><span>First detected</span><strong>${date(i.first_seen_at)}, 2026</strong></div><div><span>Detection confidence</span><strong>${Math.round(i.detection_confidence*100)}%</strong></div><div><span>Independent sightings</span><strong>${i.sightings_count}</strong></div><div><span>Nearby infrastructure</span><strong>${esc(i.asset_name)}</strong></div><div><span>Distance to asset</span><strong>${i.distance_m} metres</strong></div></div><div class="analysis-card"><h4>${icon('sun')} Why this was flagged</h4><p>${esc(i.explanation)}</p><span>Illustrative explanation · human review recommended</span></div><p class="fine-print">Source: ${esc(i.source_category)} (sample). No linked 311 record. A detection does not establish a service request.</p></div>`;}
function issueRow(i){return `<button class="issue-row" data-issue="${esc(i.issue_id)}"><span class="type-square" style="color:${categories[i.issue_type]?.color||'#4ea8ff'}">${typeIcon(i.issue_type)}</span><span class="issue-row-copy"><strong>${esc(i.issue_type)}</strong><span>${esc(i.address)}</span><small>${esc(i.issue_id)} · ${date(i.first_seen_at)} · ${esc(i.verification_status)}</small></span>${badge(i.severity)}${icon('arrow')}</button>`;}
function emptyHtml(title,description){return `<div class="empty-state">${icon('search')}<h3>${title}</h3><p>${description}</p></div>`;}
function statsHtml(issues){const values=[['database','Total records',state.issues.length,'Accessible sample dataset','blue'],['filter','Filtered results',issues.length,`${Math.round(issues.length/Math.max(1,state.issues.length)*100)}% of sample records`,'cyan'],['warning','High priority',issues.filter(i=>i.severity==='High').length,'Needs a closer look','red'],['check','Resolved',issues.filter(i=>i.resolution_status==='Resolved').length,'Marked resolved in demo','green']];return `<div class="stat-grid">${values.map(([ic,label,n,note,color])=>`<div class="stat-card ${color}"><span class="stat-icon">${icon(ic)}</span><div><span>${label}</span><strong>${n.toLocaleString()}</strong><small>${note}</small></div><span class="stat-spark">${icon('chart')}</span></div>`).join('')}</div>`;}
function dataHtml(){const rows=filtered().filter(i=>!state.scope||state.scope.includes(i.issue_id)).sort((a,b)=>{const av=a[state.sort],bv=b[state.sort];return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv)))*state.direction;});state.page=Math.min(state.page,Math.max(1,Math.ceil(rows.length/state.perPage)));const pageRows=rows.slice((state.page-1)*state.perPage,state.page*state.perPage);return `<div class="data-page">${statsHtml(rows)}<div class="records-card"><div class="table-toolbar"><div class="table-tab">${icon('database')} Issue records <span>${rows.length}</span></div><div class="table-actions">${state.scope?`<span class="scope-chip">Selected issues <button data-action="clear-scope" aria-label="Clear selection scope">×</button></span>`:'<span class="subtle-label">All accessible Toronto issues</span>'}<button class="button small" data-action="table-map">${icon('map')} View on map</button><button class="button small" data-action="export">${icon('download')} Export</button></div></div><div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-page" aria-label="Select visible rows" ${pageRows.length&&pageRows.every(i=>state.selected.includes(i.issue_id))?'checked':''}></th>${[['issue_id','Issue ID'],['issue_type','Issue type'],['severity','Severity'],['resolution_status','Status'],['neighbourhood_id','Neighbourhood'],['address','Location'],['first_seen_at','Detected'],['detection_confidence','Confidence'],['verification_status','Verification']].map(([key,title])=>`<th><button data-sort="${key}">${title}<span>${state.sort===key?(state.direction===1?'↑':'↓'):'↕'}</span></button></th>`).join('')}<th></th></tr></thead><tbody>${pageRows.map(i=>`<tr class="${state.selected.includes(i.issue_id)?'row-selected':''}"><td><input type="checkbox" data-select-id="${i.issue_id}" aria-label="Select ${i.issue_id}" ${state.selected.includes(i.issue_id)?'checked':''}></td><td><button class="table-id" data-issue="${i.issue_id}">${i.issue_id}</button></td><td><span class="table-type" style="--type-color:${categories[i.issue_type].color}">${typeIcon(i.issue_type)}${i.issue_type}</span></td><td>${badge(i.severity)}</td><td>${badge(i.resolution_status)}</td><td>${esc(i.neighbourhood_id)}</td><td class="address-cell" title="${esc(i.address)}">${esc(i.address)}</td><td>${date(i.first_seen_at)}</td><td><span class="confidence-pill">${Math.round(i.detection_confidence*100)}%</span></td><td><span class="verification-dot ${i.verification_status==='Verified'?'verified':''}"></span>${esc(i.verification_status)}</td><td><button class="icon-button" data-save="${i.issue_id}" aria-label="${state.saved.includes(i.issue_id)?'Unsave':'Save'} ${i.issue_id}">${icon('bookmark',state.saved.includes(i.issue_id)?'saved-icon':'')}</button></td></tr>`).join('')}</tbody></table>${rows.length?'':emptyHtml('No issues match these filters','Reset filters or try another area.')}</div><div class="table-pagination"><span>${rows.length?`Showing ${(state.page-1)*state.perPage+1}–${Math.min(rows.length,state.page*state.perPage)} of ${rows.length}`:'0 results'} ${state.selected.length?`<strong>· ${state.selected.length} selected</strong>`:''}</span><div><select id="page-size" aria-label="Rows per page">${[10,20,50].map(n=>`<option ${n===state.perPage?'selected':''} value="${n}">${n} per page</option>`).join('')}</select><button class="icon-button" data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Previous page">${icon('back')}</button><span class="page-number">${state.page}</span><button class="icon-button" data-page="${state.page+1}" ${state.page*state.perPage>=rows.length?'disabled':''} aria-label="Next page">${icon('arrow')}</button></div></div></div><div class="data-bottom"><div class="integration-note">${icon('code')}<div><strong>Ready for your pipeline</strong><p>Map, table, and analytics share a single issue repository. Replace the sample adapter to connect your data.</p></div><code>src/data.js → issueRepository</code></div><span class="privacy-note">${icon('shield')} Public view · approximate locations</span></div></div>`;}
function bindTable(){document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(state.sort===b.dataset.sort)state.direction*=-1;else{state.sort=b.dataset.sort;state.direction=1;}render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.page);render();});document.querySelector('#page-size').onchange=e=>{state.perPage=Number(e.target.value);state.page=1;render();};document.querySelectorAll('[data-select-id]').forEach(c=>c.onchange=()=>{state.selected=c.checked?[...new Set([...state.selected,c.dataset.selectId])]:state.selected.filter(id=>id!==c.dataset.selectId);render();});document.querySelector('#select-page').onchange=e=>{const ids=[...document.querySelectorAll('[data-select-id]')].map(c=>c.dataset.selectId);state.selected=e.target.checked?[...new Set([...state.selected,...ids])]:state.selected.filter(id=>!ids.includes(id));render();};}
function dashboardHtml(){const issues=filtered(),counts=Object.keys(categories).map(type=>({type,count:issues.filter(i=>i.issue_type===type).length})).sort((a,b)=>b.count-a.count),statuses=['Open','In review','Resolved'],colors=['#42a5f5','#ffb452','#25d5ac'];let accumulated=0;const gradient=statuses.map((s,j)=>{const start=accumulated;accumulated+=issues.filter(i=>i.resolution_status===s).length/Math.max(1,issues.length)*100;return `${colors[j]} ${start}% ${accumulated}%`;}).join(',');const dayCounts=Array.from({length:14},(_,j)=>issues.filter(i=>age(i)===13-j).length);const max=Math.max(1,...dayCounts);const points=dayCounts.map((n,j)=>`${j*40},${150-n/max*120}`).join(' ');const areas=[...new Set(issues.map(i=>i.neighbourhood_id))].map(area=>({area,count:issues.filter(i=>i.neighbourhood_id===area).length})).sort((a,b)=>b.count-a.count).slice(0,5);
  return `<div class="dashboard-page">${statsHtml(issues)}<div class="dashboard-charts"><section class="card trend-card"><div class="card-header"><h2>${icon('chart')} Detection timeline</h2><span class="subtle-label">Oct 4–17 · Sample</span></div><div class="trend-chart"><div class="chart-y"><span>${max}</span><span>${Math.ceil(max/2)}</span><span>0</span></div><svg viewBox="0 0 520 170" preserveAspectRatio="none" role="img" aria-label="Sample issue detections over the last fourteen days"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#23adfa" stop-opacity=".32"/><stop offset="100%" stop-color="#23adfa" stop-opacity="0"/></linearGradient></defs>${[30,90,150].map(y=>`<path d="M0 ${y}H520" stroke="#203346" stroke-dasharray="3 4"/>`).join('')}<polygon points="0,170 ${points} 520,170" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#3dbbff" stroke-width="3" vector-effect="non-scaling-stroke"/>${dayCounts.map((n,j)=>`<circle cx="${j*40}" cy="${150-n/max*120}" r="3.5" fill="#b4e7ff" stroke="#1a90da"><title>Oct ${j+4}: ${n} sample issues</title></circle>`).join('')}</svg></div><div class="chart-x"><span>Oct 4</span><span>Oct 8</span><span>Oct 12</span><span>Oct 17</span></div><p class="chart-caption">Observed sample detections, not a forecast.</p></section><section class="card"><div class="card-header"><h2>${icon('filter')} Issue breakdown</h2></div><div class="breakdown">${counts.map(({type,count})=>`<button data-type-filter="${type}"><span style="color:${categories[type].color}">${typeIcon(type)}</span><span>${type}</span><div class="bar-track"><i style="width:${count/Math.max(1,...counts.map(c=>c.count))*100}%;background:${categories[type].color}"></i></div><strong>${count}</strong></button>`).join('')}</div></section><section class="card"><div class="card-header"><h2>${icon('clock')} Resolution status</h2></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${issues.length?gradient:'#1b2b3e 0% 100%'})"><div><strong>${issues.length}</strong><span>Sample issues</span></div></div></div><div class="status-legend">${statuses.map((s,j)=>`<span><i style="background:${colors[j]}"></i>${s}<strong>${issues.filter(i=>i.resolution_status===s).length}</strong></span>`).join('')}</div></section></div><div class="dashboard-lower"><section class="card"><div class="card-header"><h2>${icon('pin')} Neighbourhood hotspots</h2><span class="subtle-label">Sample counts</span></div>${areas.length?areas.map(({area,count},j)=>`<button class="hotspot-row" data-area-filter="${esc(area)}"><span class="rank">${j+1}</span><span>${area}</span><div class="bar-track"><i style="width:${count/areas[0].count*100}%"></i></div><strong>${count}</strong>${icon('arrow')}</button>`).join(''):emptyHtml('No neighbourhoods','Try clearing your filters.')}</section><section class="card"><div class="card-header"><h2>${icon('clock')} Recent detections</h2><button class="text-button" data-nav="data">View all ↗</button></div>${issues.slice().sort((a,b)=>b.first_seen_at.localeCompare(a.first_seen_at)).slice(0,4).map(issueRow).join('')||emptyHtml('No detections','Try clearing your filters.')}</section><section class="card insights-card"><div class="card-header"><h2>${icon('sun')} At a glance</h2></div><div class="insight"><span class="stat-icon red">${icon('warning')}</span><div><span>Most common issue</span><strong>${counts[0]?.count?counts[0].type:'No issues'}</strong><small>${counts[0]?.count||0} of ${issues.length} filtered records</small></div></div><div class="insight"><span class="stat-icon blue">${icon('pin')}</span><div><span>Highest sample activity</span><strong>${areas[0]?.area||'No areas'}</strong><small>Based on sample record count</small></div></div><div class="insight-foot">${icon('shield')} These insights describe fictional records. Connect verified data before drawing conclusions.</div></section></div></div>`;}
function collectionHtml(){const saved=state.view==='saved',ids=saved?state.saved:state.recent;const issues=ids.map(id=>filtered().find(i=>i.issue_id===id)).filter(Boolean);return `<div class="collection-page"><div class="collection-heading"><h2>${saved?'Saved issues':'Your recent activity'} <span>${issues.length}</span></h2>${!saved?'<button class="button small" data-action="clear-recents">Clear history</button>':''}</div>${issues.length?`<div class="collection-grid">${issues.map(i=>`<article class="card saved-card"><div class="saved-card-top">${badge(i.severity)}<button class="icon-button" data-save="${i.issue_id}" aria-label="Toggle saved issue">${icon('bookmark',state.saved.includes(i.issue_id)?'saved-icon':'')}</button></div><button class="saved-card-main" data-issue="${i.issue_id}"><span class="type-orb" style="--type-color:${categories[i.issue_type].color}">${typeIcon(i.issue_type)}</span><h3>${i.issue_type}</h3><p>${esc(i.address)}</p><span>${esc(i.neighbourhood_id)} · ${date(i.first_seen_at)}</span></button><div class="saved-card-footer">${badge(i.resolution_status)}<span>${i.issue_id}</span></div></article>`).join('')}</div>`:emptyHtml(saved?'A place for the issues you care about':'Nothing here yet',saved?'Open an issue and choose Save issue. Your bookmarks stay in this browser.':'Issues you open will appear here when local history is enabled.')}</div>`;}
function verifyHtml(){if(state.role==='Public')return emptyHtml('Volunteer access required','Switch the demo account to Volunteer to preview the review workflow.');const queue=state.issues.filter(i=>i.verification_status==='Needs review');return `<div class="collection-page"><div class="notice-banner">${icon('shield')} Demo role switcher only. Production access must be enforced by your server.</div><div class="collection-heading"><h2>Awaiting a human review <span>${queue.length+state.pending.length}</span></h2></div>${state.pending.map(i=>`<div class="card pending-card"><div><span class="eyebrow">${esc(i.issue_id)} · LOCAL SUBMISSION</span><h3>${esc(i.category)}</h3><p>${esc(i.description)}</p><p>${esc(i.address)}</p></div>${badge('Pending review')}<span class="subtle-label">Privacy processing not connected</span></div>`).join('')}<div class="card review-list">${queue.map(i=>`<div class="review-item">${issueRow(i)}<div class="review-actions"><button class="button small" data-review="${i.issue_id}" data-decision="confirm">${icon('check')} Confirm sample</button><button class="button small" data-review="${i.issue_id}" data-decision="dismiss">Dismiss sample</button></div></div>`).join('')||(!state.pending.length?emptyHtml('You’re all caught up','No sample issues are waiting for review.'):'')}</div></div>`;}

function bindShell(){
  app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();nav(b.dataset.nav);});
  app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
  app.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{state.filters[el.dataset.filter]=el.value;state.page=1;clearSelection();render();});
  const search=document.querySelector('#global-search');search.oninput=()=>{state.filters.query=search.value;state.page=1;state.selected=[];state.panel=null;const caret=search.selectionStart;render();const next=document.querySelector('#global-search');next.focus();next.setSelectionRange(caret,caret);};
  document.querySelector('#role-select').onchange=e=>{state.role=e.target.value;if(state.view==='verify'&&state.role==='Public')state.view='map';render();};
  app.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toggleSave([b.dataset.save]));
  app.querySelectorAll('[data-type-filter]').forEach(b=>b.onclick=()=>{state.filters.type=b.dataset.typeFilter;nav('data');});
  app.querySelectorAll('[data-area-filter]').forEach(b=>b.onclick=()=>{state.filters.area=b.dataset.areaFilter;nav('data');});
  app.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const i=state.issues.find(i=>i.issue_id===b.dataset.review);i.verification_status=b.dataset.decision==='confirm'?'Verified':'Dismissed';toast(`Sample ${i.issue_id} ${b.dataset.decision==='confirm'?'verified':'dismissed'} for this session`);render();});
}
function bindIssueLinks(root){root.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>{if(state.view==='map')openIssue(b.dataset.issue);else{const i=state.issues.find(i=>i.issue_id===b.dataset.issue);remember(i);showModal(`<div class="modal-heading"><div><span class="eyebrow">ISSUE DETAILS</span><h2>${esc(i.issue_id)}</h2></div><button class="icon-button" data-close aria-label="Close issue">${icon('close')}</button></div>${detailHtml(i)}<div class="modal-footer"><button class="button" id="modal-save">${icon('bookmark')} ${state.saved.includes(i.issue_id)?'Remove saved':'Save issue'}</button><button class="button primary" id="modal-on-map">${icon('map')} View on map</button></div>`);document.querySelector('#modal-save').onclick=()=>{toggleSave([i.issue_id]);closeModal();};document.querySelector('#modal-on-map').onclick=()=>{closeModal();nav('map');map.flyTo(i.geometry.coordinates);openIssue(i.issue_id);};}});}
function action(name){switch(name){
  case 'upload':uploadModal();break;
  case 'reset':state.filters={query:'',type:'',severity:'',days:'30',area:'',status:'',infra:'',radius:'500'};state.scope=null;state.selected=[];state.panel=null;state.page=1;render();break;
  case 'clear-infra':state.filters.infra='';render();break;
  case 'proximity':case 'layers':infrastructureModal();break;
  case 'pan':case 'box':state.mapMode=name;render();break;
  case 'pins':case 'heat':state.heat=name==='heat';render();if(state.heat)toast('Density preview: overlapping sample issue glows.');break;
  case 'zoom-in':map?.setZoom(map.zoom+1);break;
  case 'zoom-out':map?.setZoom(map.zoom-1);break;
  case 'center':map?.flyTo([-79.397,43.661],13);break;
  case 'search-area':{const visible=filtered().filter(i=>{const [x,y]=map.position(i.geometry.coordinates);return x>=0&&y>=0&&x<=map.element.clientWidth&&y<=map.element.clientHeight;});toast(`${visible.length} sample issues in this viewport. Global filters unchanged.`);break;}
  case 'street':streetModal();break;
  case 'clear-scope':state.scope=null;state.page=1;render();break;
  case 'table-map':{const ids=state.selected.length?state.selected:filtered().filter(i=>!state.scope||state.scope.includes(i.issue_id)).map(i=>i.issue_id);const first=state.issues.find(i=>i.issue_id===ids[0]);nav('map');if(first)map.flyTo(first.geometry.coordinates,13);selectMap(ids,'multi');break;}
  case 'export':exportModal();break;
  case 'clear-recents':state.recent=[];persist('recent',[]);render();break;
  case 'settings':settingsModal();break;
  case 'help':helpModal();break;
}}

let previousFocus;
function showModal(content,wide=false){document.body.style.overflow='hidden';const root=document.querySelector('#modal-root');if(!root.children.length)previousFocus=document.activeElement;root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${content.includes('Upload')?'Upload new issue':'CivicLens dialog'}" tabindex="-1">${content}</section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();};root.querySelector('button,input,select,textarea')?.focus();}
function closeModal(){document.body.style.overflow='';document.querySelector('#modal-root').replaceChildren();if(previousFocus?.isConnected)previousFocus.focus();}
function modalHeader(eyebrow,title){return `<div class="modal-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div>`;}
function uploadModal(review=false){showModal(`${modalHeader('COMMUNITY SUBMISSION',review?'Review your issue':'Upload new issue')}<div class="step-indicator"><span class="${!review?'active':''}">1 <b>Issue details</b></span><i></i><span class="${review?'active':''}">2 <b>Review & submit</b></span></div>${review?`<div class="modal-body"><div class="review-photos">${uploadDraft.photos.map(p=>`<img src="${p.url}" alt="Photo to submit">`).join('')}</div><h3>${esc(uploadDraft.category)}</h3><p>${esc(uploadDraft.description)}</p><div class="confidence-note">${icon('pin')}<div><strong>${esc(uploadDraft.address)}</strong><span>Approximate location · confirmed by you</span></div></div><div class="notice-banner">${icon('shield')} Avoid personal information and identifiable people. Submissions require privacy processing and verification before publication.</div><p class="fine-print">Prototype mode: only the issue details are stored in this browser. Photos are previewed locally and are not uploaded. This does not create a Toronto 311 request.</p></div><div class="modal-footer"><button class="button" id="upload-back">Back to details</button><button class="button primary" id="upload-submit">Submit local demo ${icon('arrow')}</button></div>`:`<form id="upload-form"><div class="modal-body"><p class="modal-intro">Noticed something that needs attention? Give it a little context.</p><label class="upload-zone">${icon('upload')}<strong>Choose photos of the issue</strong><span>JPEG, PNG, or WebP · up to 3 photos · 10 MB each</span><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple ${uploadDraft.photos.length?'':'required'}></label><div id="photo-previews" class="photo-previews"></div><div id="upload-error" class="form-error" role="alert"></div><label class="form-label">Issue category <span>*</span><select name="category" required><option value="">Choose a category</option>${Object.keys(categories).map(t=>`<option ${uploadDraft.category===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="form-label">What did you notice? <span>*</span><textarea name="description" placeholder="Describe the issue and how it affects the public space…" minlength="10" maxlength="1000" required>${esc(uploadDraft.description)}</textarea></label><label class="form-label">Toronto address or intersection <span>*</span><div class="input-with-icon">${icon('pin')}<input name="address" placeholder="e.g. King St W & Spadina Ave, Toronto" value="${esc(uploadDraft.address)}" minlength="5" maxlength="200" required></div><small>Address lookup and pin placement connect here when geolocation is ready.</small></label><label class="checkbox-label"><input name="confirmed" type="checkbox" ${uploadDraft.confirmed?'checked':''} required> I confirm this approximate location is in Toronto.</label><p class="fine-print">Your photos stay on this device in this demo. Please avoid faces, plates, and private interiors.</p></div><div class="modal-footer"><span class="subtle-label">* Required information</span><button class="button primary" type="submit">Review issue ${icon('arrow')}</button></div></form>`}`);
  if(review){document.querySelector('#upload-back').onclick=()=>uploadModal();document.querySelector('#upload-submit').onclick=async e=>{e.target.disabled=true;try{const result=await issueRepository.submit({category:uploadDraft.category,description:uploadDraft.description,address:uploadDraft.address,created_at:new Date().toISOString()});state.pending.push(result);persist('pending',state.pending);for(const p of uploadDraft.photos)URL.revokeObjectURL(p.url);uploadDraft={photos:[],category:'',description:'',address:'',confirmed:false};showModal(`${modalHeader('LOCAL DEMO RECEIPT','Thanks for looking out.')}<div class="submission-success">${icon('shield')}<h3>Your sample issue is pending review</h3><code>${result.issue_id}</code><p>Details were saved locally. No photos were uploaded or published. Connect the submission API to send reports to your team.</p>${badge('Pending review')}</div><div class="modal-footer"><button class="button primary" data-close>Back to workspace</button></div>`);render();}catch{document.querySelector('#upload-submit').disabled=false;toast('Submission failed. Your details and photos are preserved; please retry.');}};return;}
  const form=document.querySelector('#upload-form');const saveDraft=()=>{uploadDraft.category=form.category.value;uploadDraft.description=form.description.value;uploadDraft.address=form.address.value;uploadDraft.confirmed=form.confirmed.checked;};form.oninput=saveDraft;
  const previews=()=>{document.querySelector('#photo-previews').innerHTML=uploadDraft.photos.map((p,j)=>`<div><img src="${p.url}" alt="Selected issue photo ${j+1}"><button type="button" data-remove-photo="${j}" aria-label="Remove photo ${j+1}">×</button></div>`).join('');document.querySelector('#photo-input').required=!uploadDraft.photos.length;document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{URL.revokeObjectURL(uploadDraft.photos[Number(b.dataset.removePhoto)].url);uploadDraft.photos.splice(Number(b.dataset.removePhoto),1);document.querySelector('#photo-input').value='';previews();});};previews();
  document.querySelector('#photo-input').onchange=e=>{const files=[...e.target.files];const err=files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)?'Use JPEG, PNG, or WebP files smaller than 10 MB.':files.length+uploadDraft.photos.length>3?'Choose up to 3 photos. Remove a photo before adding another.':'';document.querySelector('#upload-error').textContent=err;if(err){e.target.value='';return;}uploadDraft.photos.push(...files.map(file=>({file,url:URL.createObjectURL(file)})));previews();};
  form.onsubmit=e=>{e.preventDefault();saveDraft();if(!uploadDraft.photos.length){document.querySelector('#upload-error').textContent='Add at least one photo.';return;}uploadModal(true);};
}
function infrastructureModal(){showModal(`${modalHeader('MAP CONTEXT','Infrastructure & proximity')}<div class="modal-body"><p class="modal-intro">Add sample infrastructure to the map or narrow issues by their distance to an asset.</p><div class="notice-banner">${icon('layers')} Infrastructure points and distances are placeholders. Replace them with Toronto spatial data.</div><h3>Visible layers</h3><div class="layer-options">${['TTC','Schools','Roads'].map(t=>`<label><input type="checkbox" data-layer="${t}" ${state.layers.includes(t)?'checked':''}>${icon(t==='TTC'?'map':t==='Schools'?'database':'layers')}<span>${t}</span><small>Sample assets</small></label>`).join('')}</div><h3>Issues near infrastructure</h3><div class="form-row"><label class="form-label">Asset category<select id="infra-type"><option value="">Any infrastructure</option>${['TTC','Schools','Roads'].map(t=>`<option ${state.filters.infra===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="form-label">Distance<select id="infra-radius">${[250,500,1000,2000].map(n=>`<option value="${n}" ${String(n)===state.filters.radius?'selected':''}>Within ${n<1000?n+'m':n/1000+'km'}</option>`).join('')}</select></label></div><label class="form-label">Resolution status<select id="status-filter"><option value="">All statuses</option>${['Open','In review','Resolved'].map(s=>`<option ${state.filters.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="modal-footer"><button class="button primary" id="apply-infrastructure">Apply to workspace</button></div>`);document.querySelector('#apply-infrastructure').onclick=()=>{state.layers=[...document.querySelectorAll('[data-layer]:checked')].map(el=>el.dataset.layer);state.filters.infra=document.querySelector('#infra-type').value;state.filters.radius=document.querySelector('#infra-radius').value;state.filters.status=document.querySelector('#status-filter').value;state.page=1;clearSelection();closeModal();render();};}
function streetModal(){showModal(`${modalHeader('STREET-LEVEL EXPLORER','A closer look, coming soon')}<div class="modal-body"><div class="street-placeholder">${icon('person')}<strong>No street-level imagery connected</strong><span>Mapillary viewer integration point</span></div><p>Connect your Mapillary image lookup and viewer here to browse available photos near a dropped position.</p><p class="fine-print">Coverage, photo dates, attribution, and adjacent-image navigation depend on the provider. This prototype does not claim live street-level coverage.</p></div><div class="modal-footer"><button class="button" data-close>Return to map</button></div>`);}
function exportModal(){const rows=filtered().filter(i=>!state.scope||state.scope.includes(i.issue_id));const selected=rows.filter(i=>state.selected.includes(i.issue_id));showModal(`${modalHeader('TAKE A CLOSER LOOK','Export issue data')}<div class="modal-body"><p>Export the current filtered dataset. Public exports omit coordinates and include the location uncertainty in metres.</p><label class="form-label">Scope<select id="export-scope"><option value="filtered">Filtered results (${rows.length})</option><option value="selected" ${!selected.length?'disabled':''}>Selected rows (${selected.length})</option></select></label><label class="form-label">Format<select id="export-format"><option value="csv">CSV · spreadsheet</option><option value="geojson">GeoJSON · approximate areas</option></select></label><div class="notice-banner">${icon('shield')} Exports contain fictional records, source labels, ISO timestamps, uncertainty, and the active filters.</div></div><div class="modal-footer"><button class="button primary" id="download-export">${icon('download')} Download</button></div>`);document.querySelector('#download-export').onclick=()=>{const data=document.querySelector('#export-scope').value==='selected'?selected:rows;exportData(data,document.querySelector('#export-format').value);closeModal();};}
function exportData(rows,format){const filters=JSON.stringify(state.filters);let content,mime;
  if(format==='csv'){const headers=['issue_id','issue_type','severity','resolution_status','verification_status','neighbourhood','address','location_radius_m','first_seen_at_iso','last_seen_at_iso','sightings_count','detection_confidence','source_category','is_demo','filters_applied'];const values=rows.map(i=>[i.issue_id,i.issue_type,i.severity,i.resolution_status,i.verification_status,i.neighbourhood_id,i.address,i.location_radius_m,i.first_seen_at,i.last_seen_at,i.sightings_count,i.detection_confidence,i.source_category,true,filters]);const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};content='\uFEFF'+[headers,...values].map(row=>row.map(cell).join(',')).join('\r\n');mime='text/csv;charset=utf-8';}
  else{content=JSON.stringify({type:'FeatureCollection',is_demo:true,filters_applied:state.filters,coordinate_policy:'Approximate uncertainty areas, public demo; not exact issue positions.',features:rows.map(i=>{const [lng,lat]=i.geometry.coordinates,r=Math.max(i.location_radius_m,250),dy=r/111320,dx=dy/Math.cos(lat*Math.PI/180);return {type:'Feature',geometry:{type:'Polygon',coordinates:[Array.from({length:33},(_,j)=>{const a=j/32*Math.PI*2;return [Number((lng+dx*Math.cos(a)).toFixed(4)),Number((lat+dy*Math.sin(a)).toFixed(4))];})]},properties:{issue_id:i.issue_id,issue_type:i.issue_type,severity:i.severity,neighbourhood_id:i.neighbourhood_id,location_radius_m:r,first_seen_at:i.first_seen_at,last_seen_at:i.last_seen_at,source_category:i.source_category,is_demo:true}};})},null,2);mime='application/geo+json';}
  const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=`civiclens-sample-issues.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length} sample issues`);
}
function settingsModal(){showModal(`${modalHeader('YOUR WORKSPACE','Preferences')}<div class="modal-body"><label class="form-label">Demo account type<select id="settings-role"><option ${state.role==='Public'?'selected':''}>Public</option><option ${state.role==='Volunteer'?'selected':''}>Volunteer</option><option ${state.role==='City Staff'?'selected':''}>City Staff</option></select></label><div class="setting-row"><div><h3>Local viewing history</h3><p>Remember recently opened issues on this browser.</p></div><input id="history-toggle" type="checkbox" role="switch" aria-label="Enable viewing history" ${state.historyEnabled?'checked':''}></div><div class="setting-row"><div><h3>Saved issues</h3><p>${state.saved.length} bookmarks stored locally.</p></div><button class="button small" id="clear-saves">Clear saved</button></div><div class="setting-row"><div><h3>Local submissions</h3><p>${state.pending.length} sample submissions. Photos are never stored.</p></div><button class="button small" id="clear-pending">Clear</button></div><p class="fine-print">The account selector previews roles. Authentication, permissions, and cross-device persistence are backend integration points.</p></div><div class="modal-footer"><button class="button primary" data-close>Done</button></div>`);document.querySelector('#settings-role').onchange=e=>{state.role=e.target.value;if(state.view==='verify'&&state.role==='Public')state.view='map';render();};document.querySelector('#history-toggle').onchange=e=>{state.historyEnabled=e.target.checked;persist('historyEnabled',state.historyEnabled);};document.querySelector('#clear-saves').onclick=()=>{state.saved=[];persist('saved',[]);render();settingsModal();};document.querySelector('#clear-pending').onclick=()=>{state.pending=[];persist('pending',[]);render();settingsModal();};}
function helpModal(){showModal(`${modalHeader('A LITTLE CONTEXT','How CivicLens works')}<div class="modal-body help-content"><p>CivicLens brings civic issues from public imagery and community reports into a shared Toronto workspace.</p>${[['1','Discover','Explore issues on the map, or filter and export the same records in Data Explorer.'],['2','Understand','Open a pin to inspect evidence, approximate location, confidence, and nearby infrastructure.'],['3','Verify','A volunteer reviews findings before they become reliable public records.']].map(([n,t,d])=>`<div class="help-step"><span>${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<h3>Map controls</h3><p>Drag to pan, scroll to zoom, Shift + click to select multiple pins. Box select enables a selection rectangle. A cluster opens a list; choose Zoom in to change the viewport. Escape clears selection.</p><div class="notice-banner">${icon('code')} This is a frontend prototype. Every issue, account, confidence score, and infrastructure relationship is a placeholder. Map tiles are provided by OpenStreetMap.</div><p class="fine-print">Photos, geolocation, Mapillary, AI analysis, Toronto datasets, 311 context, authentication, and durable submissions require backend integrations.</p></div><div class="modal-footer"><button class="button primary" data-close>Got it</button></div>`);}
async function shareIssue(i){const url=new URL(location.href);url.hash=`map?issue=${i.issue_id}`;try{await navigator.clipboard.writeText(url.href);toast('Sample issue link copied');}catch{showModal(`${modalHeader('SHARE ISSUE','Copy this link')}<div class="modal-body"><input class="share-input" aria-label="Share link" readonly value="${esc(url.href)}"></div>`);document.querySelector('.share-input').select();}}
document.addEventListener('keydown',e=>{const modal=document.querySelector('.modal');if(e.key==='Escape'){if(modal)closeModal();else clearSelection();}if(e.key==='/'&&!modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();document.querySelector('#global-search')?.focus();}if(e.key==='Tab'&&modal){const els=[...modal.querySelectorAll('button,input,textarea,select,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
async function start(){try{state.issues=await issueRepository.list();const route=location.hash.slice(1).split('?')[0];if(['map','data','dashboard','saved','recents'].includes(route))state.view=route;render();const issue=new URLSearchParams(location.hash.split('?')[1]||'').get('issue');if(issue){state.view='map';render();const record=state.issues.find(i=>i.issue_id===issue);if(record){map.flyTo(record.geometry.coordinates);openIssue(issue);}}}catch(error){app.innerHTML='<div class="load-error"><h1>Couldn’t load the workspace</h1><p>Check your issue repository connection and reload.</p><button onclick="location.reload()">Retry</button></div>';console.error(error);}}
start();
